import{_ as t,c as a,o,ae as i}from"./chunks/framework.2MVDia4S.js";const u=JSON.parse('{"title":"RFC 0002: Lightweight client-neutral execution consensus","description":"","frontmatter":{},"headers":[],"relativePath":"rfc/0002-lightweight-client-neutral-protocol.md","filePath":"rfc/0002-lightweight-client-neutral-protocol.md"}'),n={name:"rfc/0002-lightweight-client-neutral-protocol.md"};function r(l,e,s,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="rfc-0002-lightweight-client-neutral-execution-consensus" tabindex="-1">RFC 0002: Lightweight client-neutral execution consensus <a class="header-anchor" href="#rfc-0002-lightweight-client-neutral-execution-consensus" aria-label="Permalink to &quot;RFC 0002: Lightweight client-neutral execution consensus&quot;">​</a></h1><ul><li><strong>Status:</strong> Implemented as protocol v2; production acceptance pending</li><li><strong>Target:</strong> EthBFT v0.3</li><li><strong>Supersedes:</strong> RFC 0001 protocol-v1 wire format</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Define the smallest deterministic interface that lets a BFT system decide Ethereum execution without duplicating execution-client responsibilities or depending on one client&#39;s private RPC extensions.</p><h2 id="responsibilities" tabindex="-1">Responsibilities <a class="header-anchor" href="#responsibilities" aria-label="Permalink to &quot;Responsibilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Owns</th></tr></thead><tbody><tr><td>Execution client</td><td>EVM, state, txpool, transaction P2P, payload construction and validation</td></tr><tr><td>CometBFT</td><td>validator networking, proposal dissemination, votes, finality</td></tr><tr><td>EthBFT</td><td>deterministic payload envelope, Engine API lifecycle, commit recovery</td></tr></tbody></table><p>EthBFT MUST NOT maintain a user-transaction mempool or authoritative receipt index. Users MUST submit transactions to an EL JSON-RPC endpoint. CometBFT MUST run its transaction mempool in <code>nop</code> mode.</p><h2 id="engine-api-profile" tabindex="-1">Engine API profile <a class="header-anchor" href="#engine-api-profile" aria-label="Permalink to &quot;Engine API profile&quot;">​</a></h2><p>At startup the adapter calls <code>engine_exchangeCapabilities</code> and MUST stop if the EL lacks methods required by any configured fork:</p><table tabindex="0"><thead><tr><th>Fork profile</th><th>Build</th><th>Retrieve</th><th>Validate</th></tr></thead><tbody><tr><td>Shanghai</td><td><code>forkchoiceUpdatedV2</code></td><td><code>getPayloadV2</code></td><td><code>newPayloadV2</code></td></tr><tr><td>Cancun</td><td><code>forkchoiceUpdatedV3</code></td><td><code>getPayloadV3</code></td><td><code>newPayloadV3</code></td></tr><tr><td>Prague</td><td><code>forkchoiceUpdatedV3</code></td><td><code>getPayloadV4</code></td><td><code>newPayloadV4</code></td></tr></tbody></table><p>All calls use one JWT-authenticated endpoint. Client identification is diagnostic only and MUST NOT alter consensus behavior.</p><h2 id="proposal-format" tabindex="-1">Proposal format <a class="header-anchor" href="#proposal-format" aria-label="Permalink to &quot;Proposal format&quot;">​</a></h2><p>A proposal contains exactly one byte string:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;ETHBFT&quot; || 0x00 || 0x02 || RLP(protocol-v2 fields)</span></span></code></pre></div><p>The RLP commits to Engine API version, chain ID, consensus height, previous app hash, the complete execution payload, optional parent beacon block root, versioned blob hashes, and Prague execution requests. Decoding MUST reject non-canonical encoding, trailing bytes, unexpected fork fields, unordered request types, a reconstructed block-hash mismatch, or a payload above the configured limit.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><ol><li><code>PrepareProposal</code> derives deterministic payload attributes from committed state and consensus height/time, asks the proposer EL to build, validates locally, and returns one envelope.</li><li><code>ProcessProposal</code> requires exactly one envelope, validates all deterministic fields, reconstructs its Ethereum block hash, and calls the matching <code>newPayload</code> method. Only <code>VALID</code> is accepted.</li><li><code>FinalizeBlock</code> repeats validation, persists a commit intent, and advances head/safe/finalized to the decided payload.</li><li><code>Commit</code> atomically stores height, execution hash, and app hash and clears the intent. Startup replays a surviving intent.</li></ol><h2 id="determinism-and-upgrades" tabindex="-1">Determinism and upgrades <a class="header-anchor" href="#determinism-and-upgrades" aria-label="Permalink to &quot;Determinism and upgrades&quot;">​</a></h2><p>The protocol fingerprint covers chain ID, execution genesis, fork timestamps, fee recipient, and maximum payload size. A mismatch MUST stop startup. Fork schedule or envelope changes therefore require an explicit coordinated network upgrade; automatic local inference is forbidden.</p><h2 id="safety-properties" tabindex="-1">Safety properties <a class="header-anchor" href="#safety-properties" aria-label="Permalink to &quot;Safety properties&quot;">​</a></h2><ul><li>no payload is voted without local EL validation;</li><li>no EL forkchoice is advanced before a BFT decision;</li><li><code>SYNCING</code>, <code>ACCEPTED</code>, malformed, timed-out, and inconsistent results are fail-closed;</li><li>each validator uses an independent EL/datadir, with EthBFT as its sole forkchoice authority;</li><li>readiness is false while either the EL or CometBFT is catching up.</li></ul><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-goals&quot;">​</a></h2><p>This protocol is not an Ethereum-mainnet bridge, beacon consensus client, cross-chain proof system, wallet RPC proxy, block explorer, or validator governance mechanism.</p><h2 id="open-production-work" tabindex="-1">Open production work <a class="header-anchor" href="#open-production-work" aria-label="Permalink to &quot;Open production work&quot;">​</a></h2><p>ABCI state sync, validator replacement, mixed-client conformance, Byzantine fault injection, upgrade governance, load envelopes, and independent audit are acceptance gates, not implicit properties of this RFC.</p>',25)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
